<?php require_once __DIR__.'/../auth.php';require_admin();$page_title='Admin - Books';$q=trim($_GET['q']??'');$like="%$q%";$s=$conn->prepare('SELECT * FROM books WHERE title LIKE ? OR author LIKE ? ORDER BY id DESC');$s->bind_param('ss',$like,$like);$s->execute();$books=$s->get_result();$root_prefix='../';$asset_prefix='../';include __DIR__.'/../header.php';?><div class="row"><h1>Admin · Manage books</h1><a class="button" href="book_form.php">+ Add book</a></div><form class="search" method="get"><input name="q" value="<?= htmlspecialchars($q) ?>" placeholder="Search title or author"><button>Search</button></form><div class="table-wrap"><table><tr><th>Title</th><th>Author</th><th>Category</th><th>Price</th><th>Actions</th></tr><?php while($b=$books->fetch_assoc()): ?><tr><td><?= htmlspecialchars($b['title']) ?></td><td><?= htmlspecialchars($b['author']) ?></td><td><?= htmlspecialchars($b['category']) ?></td><td>₹<?= number_format((float)$b['price'],2) ?></td><td><a href="book_form.php?id=<?= (int)$b['id'] ?>">Edit</a> | <form class="inline" method="post" action="delete_book.php" onsubmit="return confirm('Delete this book?')"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><button class="danger">Delete</button></form></td></tr><?php endwhile; ?></table></div><?php include __DIR__.'/../footer.php'; ?>